  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 3 }], // €255, VAT 21%: €53.55
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const result = vatSummary([issued1, issued2]);

  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 68000); // 42500 + 25500
  assert.equal(result[0].vat, 14280); // 8925 + 5355
});

test('vatSummary aggregates by VAT rate across invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-01',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }, // €425, VAT 21%
      { sku: 'PRINT-A4', qty: 30 }, // €37 * 30 = €1110, VAT 9%
    ],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-05',
    lines: [
      { sku: 'DES-HOUR', qty: 2 }, // €170, VAT 21%
      { sku: 'PRINT-A4', qty: 30 }, // €37 * 30 = €1110, VAT 9%
    ],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const result = vatSummary([issued1, issued2]);

  assert.equal(result.length, 2);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 59500); // 42500 + 17000
  assert.equal(result[0].vat, 12495); // 8925 + 3570
  assert.equal(result[1].rate, 9);
  assert.equal(result[1].base, 2220); // 1110 + 1110 (37 * 30 each)
  assert.equal(result[1].vat, 200); // roundCents(1110 * 9 / 100) * 2 = roundCents(99.9) * 2 = 100 * 2
});

test('vatSummary with mixed invoice statuses', () => {
  const draft = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }], // should be excluded
  }).value;

  let inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 3 }], // €255, VAT 21%: €53.55
  }).value;
  const issued2 = issueInvoice(inv2, []).value;

  let inv3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 2 }], // €170, VAT 21%: €35.70
  }).value;
  let issued3 = issueInvoice(inv3, ['INV-2025-0001']).value;
  issued3 = recordPayment(issued3, { amount: 20570, date: '2025-10-15' }).value;
  assert.equal(issued3.status, 'paid');

  const result = vatSummary([draft, issued2, issued3]);

  // Should only include issued2 and issued3, not draft
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 42500); // only 25500 + 17000
  assert.equal(result[0].vat, 8925); // only 5355 + 3570
});

test('vatSummary with complex discounts and multiple VAT rates', () => {
  const invoice = createInvoice({
    customerId: 'C-001', // gold tier, 5% discount
    issueDate: '2025-10-15',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 }, // €1200, 5% discount €60, net €1140, VAT 21%: €239.40
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 }, // €850, 10% discount €85, net €765, VAT 21%: €160.65
      { sku: 'BOOK-DESIGN', qty: 5 }, // €124.50 * 5 = €622.50, 5% tier discount €31.13, net €591.37, VAT 9%: €53.22
    ],
  }).value;
  const issued = issueInvoice(invoice, []).value;

  const result = vatSummary([issued]);

  assert.equal(result.length, 2);
  assert.equal(result[0].rate, 21);
  assert.equal(result[0].base, 190500); // 114000 + 76500
  assert.equal(result[0].vat, 40005); // 23940 + 16065
  assert.equal(result[1].rate, 9);
  assert.equal(result[1].base, 11828); // 2490 * 5 - (2490 * 5 * 5 / 100) rounded
  assert.equal(result[1].vat, 1065); // 11828 * 9 / 100 rounded
});

